import{z as l,x as s,o as n,c as d,q as B,j as i,D as e,d as E,s as A,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"公司金融深化收束","description":"","frontmatter":{"title":"公司金融深化收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cf-map.md","filePath":"econ/cf-map.md","lastUpdated":1791413859000}'),p={name:"econ/cf-map.md"};function C(c,a,f,h,m,u){const t=s("Mermaid");return n(),d("div",null,[a[2]||(a[2]=B('<h1 id="公司金融深化收束" tabindex="-1">公司金融深化收束 <a class="header-anchor" href="#公司金融深化收束" aria-label="Permalink to &quot;公司金融深化收束&quot;">​</a></h1><div class="epigraph"><p>这门课做的其实是同一件事：把主干里「假设没有」的东西一样样请回来——约束、时机、控制权、外部性、失败；每请回一样，工具箱就多一格。</p><footer>—— 据 Modigliani–Miller 1958 与本课程各课整理</footer></div><p><a href="/econ/cf-bankruptcy-restructuring">上一课</a>把破产与重整钉在程序与激励上，本课程到此收束。七课连起来读是一条单线：MM 1958 把摩擦全部拿走之后，公司金融只剩一条 NPV 规则（<a href="/econ/npv-irr-pitfalls">NPV 与 IRR 的陷阱</a>守着它的用法）；本课程每次请回一种摩擦，就多出一种工具——融资约束的度量请回信息摩擦与抵押品，股利与回购请回承诺需求，IPO 与发行时机请回市场情绪，并购浪潮请回估值差与同时性冲击，治理实证请回选择的内生性，ESG 请回外部性与目标函数，破产重整请回谈判与程序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>七课共有的约束是什么。每课的失效模式相同：把代理当结论，把相关当因果。融资约束课上，投资-现金流敏感度被当过约束本身；治理课上，条款指数的横截面差被当过侵蚀效应；ESG 课上，评级分数被当过企业表现。共同的后设教训是：公司金融的每个可观测变量都被需求与供给、选择与均衡同时推动，单独读一个都会错。</p><p><span class="marginnote">「代理有双重身份」可以翻译成：一个数同时打两份工。现金流既是投资机会的信号，又是可动用的资金——你观察到「现金流高的公司投资多」，分不清是机会在推还是钱在推。凡是一数两用，单独读它都会错，这就是每课失效模式的共同源头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是给七课的共识配一张定位协议：任何一篇公司金融实证文字，放上三张清单——度量、识别、机制——逐项查代理有没有双重身份、识别有没有可信的设计、结论走哪条管道。用法是先定位再评价：三张都过得去，关于结论的争论才有共同的桌面；过不去的格子本身，就是对该文最直接的批评。</p><h3 id="三张清单" tabindex="-1">三张清单 <a class="header-anchor" href="#三张清单" aria-label="Permalink to &quot;三张清单&quot;">​</a></h3><p>把任何一篇公司金融实证文字放上三张清单来定位。<strong>度量清单</strong>：代理有没有双重身份（现金流既是机会也是资金）、指数系数是否出域、评级口径是否声明。<strong>识别清单</strong>：有没有只推一侧的冲击（养老金供款推资金侧）、有没有法律时间差之类的准实验、固定效应能挡住哪类反向因果。<strong>机制清单</strong>：结论走哪条管道——门槛利率、承诺、纪律、控制权、程序，每条管道各有可检验含义。这与<a href="/econ/corporate-finance-identification">公司金融的实证识别</a>的主张一脉相承：先有设计，再谈机制是哪一条。</p><p><span class="marginnote">直觉类比：三张清单像海关的三道闸——第一道查行李里有没有别人托带的东西（代理双重身份），第二道查通行章是真是假（识别设计），第三道查你到底要从哪个门出去（机制管道）。三道都过，才轮到评价货本身的好坏。</span></p>',11)),(n(),i(o,null,{default:e(()=>[A(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONS%5B%22%E7%BA%A6%E6%9D%9F%E7%9A%84%E5%BA%A6%E9%87%8F%22%5D%20--%3E%20PAYOUT%5B%22%E5%88%86%E9%85%8D%EF%BC%9A%E8%82%A1%E5%88%A9%E4%B8%8E%E5%9B%9E%E8%B4%AD%22%5D%0A%20%20PAYOUT%20--%3E%20ISSUE%5B%22%E5%8F%91%E8%A1%8C%E4%B8%8E%E6%97%B6%E6%9C%BA%22%5D%0A%20%20ISSUE%20--%3E%20MA%5B%22%E5%B9%B6%E8%B4%AD%E6%B5%AA%E6%BD%AE%22%5D%0A%20%20MA%20--%3E%20GOV%5B%22%E6%B2%BB%E7%90%86%E5%AE%9E%E8%AF%81%22%5D%0A%20%20GOV%20--%3E%20ESG%5B%22%E7%9B%AE%E6%A0%87%E6%89%A9%E5%B1%95%22%5D%0A%20%20ESG%20--%3E%20BR%5B%22%E7%A0%B4%E4%BA%A7%E4%B8%8E%E9%87%8D%E6%95%B4%22%5D%0A%20%20BR%20--%3E%20LOOP%7B%22%E5%8F%8D%E9%A6%88%E5%9B%9E%E8%B5%84%E6%9C%AC%E7%BB%93%E6%9E%84%22%7D%20--%3E%20CONS%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[E("框架的生成力可以从未竟问题上看。其一，非上市企业与银行主导体系的融资约束度量——本课程的指数几乎全是上市样本，而约束最紧的恰是样本之外的企业。其二，双层股权与创始人控制对长期创新的影响："),r("a",{href:"/econ/family-firms-pyramids"},"家族企业与金字塔"),E("给了结构工具，因果仍欠设计。其三，ESG 披露规则的均衡效应：验证技术变了，门槛利率渠道与代理渠道的相对价格会重排。文献骨架有五根柱子：Modigliani–Miller 1958 给无关性原点，Myers–Majluf 1984 给摩擦的形状，Jensen 1986 给代理问题，Baker–Wurgler 2002 给择时进入资本结构，Loughran–Ritter 2002 给发行的行为侧——课程顺序与文献顺序大体同构，这是学科的积累方式。")],-1)),(n(),i(o,null,{default:e(()=>[A(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%B8%80%E7%AF%87%E5%85%AC%E5%8F%B8%E9%87%91%E8%9E%8D%E5%AE%9E%E8%AF%81%E8%AE%BA%E6%96%87%22%5D%20--%3E%20C1%7B%22%E5%BA%A6%E9%87%8F%EF%BC%9A%E4%BB%A3%E7%90%86%E6%9C%89%E4%B8%80%E6%95%B0%E4%B8%A4%E7%94%A8%E5%90%97%3F%22%7D%0A%20%20C1%20--%3E%7C%E6%9C%89%E4%B8%94%E6%9C%AA%E5%A3%B0%E6%98%8E%7C%20F1%5B%22%E8%AF%BB%E6%95%B0%E5%85%88%E6%89%93%E9%97%AE%E5%8F%B7%22%5D%0A%20%20C1%20--%3E%7C%E6%B8%85%E6%A5%9A%7C%20C2%7B%22%E8%AF%86%E5%88%AB%EF%BC%9A%E6%9C%89%E5%8F%AA%E6%8E%A8%E4%B8%80%E4%BE%A7%E7%9A%84%E5%86%B2%E5%87%BB%E5%90%97%3F%22%7D%0A%20%20C2%20--%3E%7C%E6%B2%A1%E6%9C%89%7C%20F2%5B%22%E7%9B%B8%E5%85%B3%E4%B8%8D%E7%AD%89%E4%BA%8E%E5%9B%A0%E6%9E%9C%22%5D%0A%20%20C2%20--%3E%7C%E6%9C%89%7C%20C3%7B%22%E6%9C%BA%E5%88%B6%EF%BC%9A%E7%BB%93%E8%AE%BA%E8%B5%B0%E5%93%AA%E6%9D%A1%E7%AE%A1%E9%81%93%3F%22%7D%0A%20%20C3%20--%3E%20U%5B%22%E4%B8%89%E6%A0%BC%E9%83%BD%E8%BF%87%EF%BC%8C%E4%BA%89%E8%AE%BA%E6%89%8D%E6%9C%89%E5%85%B1%E5%90%8C%E6%A1%8C%E9%9D%A2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">五篇骨架横跨 1958–2002：MM 给原点，Myers–Majluf 给摩擦，Jensen 给代理，Baker–Wurgler 与 Loughran–Ritter 给市场侧。每个十年回答上一层留下的「假设」——读新文献时先找它拆的是哪根柱子的哪块假设。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程的边界要交代清楚。始终站在企业决策侧：资本成本只是外生输入，它的定价理论是资产定价课程的事；企业风险管理只以<a href="/econ/corporate-hedging-rationale">公司对冲的理由</a>为界，没有展开。银行作为资金供给方与债权人的完整理论——挤兑、监管资本、救助决策——是下一课程「银行与中介深化」的领域；家庭金融与国际公司金融只在衔接处提及。收束不等于问题解决：这门课给的是定位新问题的坐标系与三张清单，不是答案的清单。</p><p><span class="marginnote">常见误区：以为收束课是「答案汇总」。它给的是坐标系——读完这七课，你该能在读到「某指数显示…」「回归发现…」时先问三件事：度量哪来的、识别怎么做的、机制走哪条，而不是背结论。结论会随样本与制度老化，定位协议不会。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>七课一条线：度量、分配、发行、并购、治理、目标、程序，每课请回一种摩擦并给出对应工具。</li><li>共同骨架是信息不对称与代理问题的组合；共同失效模式是「代理当结论、相关当因果」。</li><li>三张清单（度量、识别、机制）用于定位任何公司金融实证文字。</li><li>与定价侧分工：本课程始终在企业决策侧，资本成本是外生输入。</li><li>文献骨架五篇钉五根柱子：Modigliani–Miller 1958；Myers–Majluf 1984；Jensen 1986；Baker–Wurgler 2002；Loughran–Ritter 2002。</li></ul>',6))])}const _=l(p,[["render",C]]);export{g as __pageData,_ as default};
